//! KDL emitter for a `binds { ... }` fragment.

use std::collections::HashMap;

use crate::spec::{Action, OverlayTitle, Spec};

pub const HEADER: &str = "\
// Generated by spikes/r6-binds (spike R6) — do not edit by hand.
// Wire it into ~/.config/niri/config.kdl once with:
//     include \"shell-binds.kdl\"
";

pub fn fragment(spec: &Spec) -> Result<String, String> {
    check_conflicts(spec)?;

    let mut out = String::from(HEADER);
    out.push('\n');
    out.push_str("binds {\n");
    for bind in &spec.binds {
        let mut props: Vec<String> = Vec::new();
        if let Some(repeat) = bind.repeat {
            props.push(format!("repeat={repeat}"));
        }
        if let Some(ms) = bind.cooldown_ms {
            props.push(format!("cooldown-ms={ms}"));
        }
        if bind.allow_when_locked {
            props.push("allow-when-locked=true".to_string());
        }
        match &bind.overlay_title {
            Some(OverlayTitle::Text(t)) => props.push(format!("hotkey-overlay-title={}", string(t))),
            Some(OverlayTitle::Null) => props.push("hotkey-overlay-title=null".to_string()),
            None => {}
        }

        out.push_str("    // ");
        out.push_str(&bind.id);
        out.push('\n');
        out.push_str("    ");
        out.push_str(&bind.combo.kdl());
        for p in &props {
            out.push(' ');
            out.push_str(p);
        }
        out.push_str(" { ");
        out.push_str(&action(&bind.action, &spec.ipc_command)?);
        out.push_str(" }\n");
    }
    out.push_str("}\n");

    if spec.skip_hotkey_overlay_at_startup {
        out.push_str("\nhotkey-overlay {\n    skip-at-startup\n}\n");
    }
    Ok(out)
}

fn action(action: &Action, ipc_command: &[String]) -> Result<String, String> {
    let line = match action {
        Action::Spawn(command) => {
            let mut s = String::from("spawn");
            for arg in command {
                s.push(' ');
                s.push_str(&string(arg));
            }
            s
        }
        Action::SpawnSh(command) => format!("spawn-sh {}", string(command)),
        Action::Niri { action, args } => {
            let mut s = action.clone();
            for arg in args {
                s.push(' ');
                s.push_str(&arg_literal(arg));
            }
            s
        }
        Action::Ipc { call } => {
            let mut s = String::from("spawn");
            for arg in ipc_command {
                s.push(' ');
                s.push_str(&string(arg));
            }
            s.push(' ');
            s.push_str(&string("call"));
            s.push(' ');
            s.push_str(&string(call));
            s
        }
    };
    Ok(format!("{line};"))
}

/// niri argument: bare when it is an integer (workspace index, width in px),
/// quoted otherwise (`set-column-width "+10%"`, `focus-monitor "HDMI-A-1"`).
fn arg_literal(arg: &str) -> String {
    if arg.parse::<i64>().is_ok() {
        arg.to_string()
    } else {
        string(arg)
    }
}

fn string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// niri rejects duplicate keybinds at parse time, and its keybind identity is a
/// *set* of modifiers: `Mod+Shift+Q` and `Shift+Mod+Q` are the same bind. Detect
/// that before writing a file the compositor would refuse.
fn check_conflicts(spec: &Spec) -> Result<(), String> {
    let mut seen: HashMap<String, &str> = HashMap::new();
    for bind in &spec.binds {
        let key = bind.combo.kdl();
        if let Some(previous) = seen.get(&key) {
            return Err(format!(
                "duplicate keybind `{key}`: binds.{previous} and binds.{} use the same combo",
                bind.id
            ));
        }
        seen.insert(key, &bind.id);
    }
    Ok(())
}

/// niri only accepts `allow-when-locked` on spawn binds (spawn and spawn-sh);
/// on anything else it fails to load the config, so refuse it earlier.
pub fn check_locked(spec: &Spec) -> Result<(), String> {
    for bind in &spec.binds {
        if bind.allow_when_locked && !matches!(bind.action, Action::Spawn(_) | Action::SpawnSh(_)) {
            return Err(format!(
                "binds.{}: allow_when_locked is only allowed on spawn/spawn-sh binds, not on `{}`",
                bind.id,
                bind.action.kind()
            ));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::spec::load;

    #[test]
    fn minimal_fragment() {
        let spec = load(
            r#"{"binds":{"terminal":{"keys":"SUPER+Return","do":{"type":"spawn","command":["foot"]}}}}"#,
        )
        .unwrap();
        let kdl = fragment(&spec).unwrap();
        assert!(kdl.contains("    Mod+Return { spawn \"foot\"; }\n"), "{kdl}");
        assert!(!kdl.contains("SUPER"));
    }

    #[test]
    fn ipc_and_quoted_args() {
        let spec = load(
            r#"{"binds":{
                "launcher":{"keys":"SUPER+D","do":{"type":"ipc","call":"launcher.toggle"}},
                "wider":{"keys":"SUPER+Plus","do":{"type":"niri","action":"set-column-width","args":["+10%"]}},
                "ws2":{"keys":"SUPER+2","do":{"type":"niri","action":"focus-workspace","args":["2"]}}
            }}"#,
        )
        .unwrap();
        let kdl = fragment(&spec).unwrap();
        assert!(
            kdl.contains("spawn \"shellctl\" \"call\" \"launcher.toggle\";"),
            "{kdl}"
        );
        assert!(kdl.contains("set-column-width \"+10%\";"), "{kdl}");
        assert!(kdl.contains("focus-workspace 2;"), "{kdl}");
    }

    #[test]
    fn different_modifier_sets_do_not_collide() {
        let spec = load(
            r#"{"binds":{
                "a":{"keys":"SUPER+Q","do":{"type":"spawn","command":["true"]}},
                "b":{"keys":"SHIFT+SUPER+Q","do":{"type":"spawn","command":["true"]}}
            }}"#,
        )
        .unwrap();
        assert!(
            fragment(&spec).is_ok(),
            "Mod+Q and Mod+Shift+Q are different binds"
        );
    }

    #[test]
    fn duplicate_combo_is_refused() {
        let spec = load(
            r#"{"binds":{
                "a":{"keys":"SUPER+SHIFT+Q","do":{"type":"spawn","command":["true"]}},
                "b":{"keys":"SHIFT+SUPER+Q","do":{"type":"spawn","command":["true"]}}
            }}"#,
        )
        .unwrap();
        assert!(fragment(&spec).unwrap_err().contains("duplicate keybind"));
    }

    #[test]
    fn locked_only_for_spawn() {
        let spec = load(
            r#"{"binds":{
                "o":{"keys":"SUPER+O","do":{"type":"niri","action":"toggle-overview"},"allow_when_locked":true}
            }}"#,
        )
        .unwrap();
        assert!(check_locked(&spec).unwrap_err().contains("only allowed on spawn"));
    }
}
